export function initPage(){const input=document.getElementById('disclosure-query');if(!input)return;const cards=[...document.querySelectorAll('[data-disclosure-card]')],empty=document.getElementById('disclosure-empty');const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const show=()=>{const q=normalize(input.value.trim());let count=0;cards.forEach(card=>{card.hidden=!normalize(card.dataset.search).includes(q);if(!card.hidden)count++});empty.hidden=count>0;};input.addEventListener('input',show);}
if(!window.MTPageRouter?.booting){if(window.MTPageRouter)window.MTPageRouter.run(initPage);else initPage();}
